package com.example.demo.model; public class Product { private Long id; private String name; private double price; public Product(){} public Product(Long id,String name,double price){this.id=id;this.name=name;this.price=price;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getName(){return name;} public void setName(String n){name=n;} public double getPrice(){return price;} public void setPrice(double p){price=p;} }